0// StudentApplications.jsx — Updated to match class diagram
// Fixes:
//   - applicationStatus: pending / accepted / rejected (class diagram enum)
//   - InternshipAgreement: startDate, endDate, validated, generatePDF()
//   - application.accept() / application.refuse() reflected in timeline
//   - Download Convention de Stage button wired to internshipAgreement.generatePDF()

import { useState } from "react";
import StudentLayout from "./StudentLayout";


// ── Class diagram: applicationStatus enum ──
// pending | accepted | rejected (note: diagram says "rejected" not "refused")
const STATUS_MAP = {
  pending:  { label:"Pending",  badge:"badge-orange", dot:"bg-[#d4a84b]",  icon:"⏳", msg:"Awaiting company decision." },
  accepted: { label:"Accepted", badge:"badge-green",  dot:"bg-[#e8a09a]",icon:"✅", msg:"Your application was accepted! Agreement being prepared." },
  rejected: { label:"Rejected", badge:"badge-red",    dot:"bg-[#d4849a]",    icon:"❌", msg:"Your application was not selected this time." },
};

// ── Class diagram: InternshipAgreement ──
// startDate, endDate, validated: boolean, generatePDF()
const AGREEMENTS = {
  2: { startDate:"May 05, 2025", endDate:"Sep 05, 2025", validated: true,  ref:"AGR-2025-0042" },
};

// ── Application data ──
const APPLICATIONS = [
  {
    id:1, company:"Sonatrach Digital", logo:"🛢️", role:"Full-Stack Developer",
    wilaya:"Alger", type:"On-site", duration:"6 months",
    appliedDate:"Apr 20, 2025",
    status:"pending", // applicationStatus enum
    skills:["React","Node.js","PostgreSQL"],
    timeline:[
      {label:"Applied",             date:"Apr 20",  done:true  },
      {label:"Profile reviewed",    date:"Apr 22",  done:true  },
      {label:"Company decision",    date:"—",        done:false },
      {label:"Admin validation",    date:"—",        done:false },
      {label:"Agreement generated", date:"—",        done:false },
    ],
  },
  {
    id:2, company:"Ooredoo Labs", logo:"🌐", role:"Data Analyst",
    wilaya:"Alger", type:"Hybrid", duration:"4 months",
    appliedDate:"Apr 12, 2025",
    status:"accepted", // application.accept() was called
    skills:["Python","SQL","Power BI"],
    timeline:[
      {label:"Applied",             date:"Apr 12",  done:true },
      {label:"Profile reviewed",    date:"Apr 14",  done:true },
      {label:"Company decision",    date:"Apr 17",  done:true },
